# -*- coding: utf-8 -*-
"""Atlas des idees — deuxieme annee, chapitre 3 (2/3).

Verifications empiriques, theories contemporaines : neo-factorielles,
neo-technologiques, analyses de la demande, Krugman et la geographie.
"""

ENR = {}
SPLIT = {}

SPLIT[23] = [

 ('Wassily Leontief', "Le paradoxe de Leontief : confronter le modèle HOS aux données", {
  'affirme': "Leontief soutient qu’un modèle théorique doit être confronté aux données, et il entreprend cette confrontation pour le modèle Heckscher-Ohlin-Samuelson à partir de ses propres tableaux entrées-sorties. Le modèle prédit qu’un pays exporte les biens intensifs en son facteur relativement abondant. Les États-Unis étant, au début des années 1950, l’économie la mieux dotée en capital, leurs exportations devraient donc être nettement plus intensives en capital que les productions nationales substituables à leurs importations. Leontief constate l’inverse : les exportations américaines apparaissent moins intensives en capital que ces productions de substitution. Le résultat est suffisamment net et suffisamment contraire à l’attente pour recevoir le nom de paradoxe. Leontief ne conclut pas pour autant à la fausseté du raisonnement : il établit qu’un élément essentiel manque à la définition des facteurs, et ouvre ainsi la voie à une révision plutôt qu’à un abandon.",
  'mecanisme': "Trois maillons. Un : la méthode consiste à calculer, à partir des tableaux entrées-sorties, les quantités de capital et de travail incorporées dans un panier représentatif d’exportations et dans un panier de productions substituables aux importations. Deux : la comparaison des intensités factorielles de ces deux paniers permet de tester directement la prédiction du théorème. Trois : le résultat obtenu étant contraire à l’attente, deux interprétations seulement sont possibles — soit le modèle est faux, soit la nomenclature des facteurs est insuffisante. Leontief oriente vers la seconde en suggérant que le travail américain n’est pas comparable au travail étranger : il incorpore davantage de formation et d’efficacité, ce qui annonce la prise en compte de l’hétérogénéité du travail.",
  'exemple': "Le cours souligne que Leontief confronte le modèle aux données, démarche rare dans la théorie du commerce de l’époque, et que son résultat ouvre la voie à l’hétérogénéité du travail.",
  'portee': "Dans le chapitre, le paradoxe de Leontief joue un rôle charnière : il clôt l’exposé du modèle HOS et ouvre celui des approches néo-factorielles et néo-technologiques. Il illustre aussi une leçon de méthode que le cours met en avant : une anomalie empirique conduit plus souvent à redéfinir les concepts qu’à abandonner le cadre théorique, et c’est précisément cette redéfinition qui fait progresser l’analyse.",
  'diss': "Référence précieuse pour les sujets de méthode et pour montrer comment une théorie se révise. À mobiliser aussi pour nuancer toute application mécanique du théorème H-O aux données observées.",
  'copie': "Leontief confronte en 1953 le modèle HOS aux données américaines et constate que les exportations des États-Unis sont moins intensives en capital que les productions substituables aux importations : le paradoxe oblige à redéfinir les facteurs plutôt qu’à rejeter le raisonnement.",
  'ouvrage': "« Domestic Production and Foreign Trade : The American Capital Position Re-examined », 1953",
  'notions': ['Paradoxe de Leontief', 'Modèle HOS', 'Intensité factorielle'],
  'liens': [('Bertil Ohlin', 'opposition', "Le test contredit la prédiction du théorème H-O pour l’économie la mieux dotée en capital."),
            ('Robert Baldwin', 'prolonge', "Baldwin résout le paradoxe en montrant que la dotation décisive est la qualification et le savoir technologique."),
            ('D. Keesing', 'prolonge', "L’approche néo-factorielle tire la conséquence du paradoxe en désagrégeant le facteur travail.")],
 }),

 ('Robert Baldwin', "La dotation décisive est le travail qualifié et le savoir technologique", {
  'affirme': "Baldwin soutient que le paradoxe de Leontief se dissout dès que l’on cesse de traiter le travail comme un facteur homogène. Reprenant une méthodologie proche de celle de Leontief, il montre en 1971 que les exportations américaines, si elles ne sont pas particulièrement intensives en capital physique, le sont très nettement en travail qualifié et en savoir technologique. Le modèle HOS n’est donc pas réfuté : c’est la nomenclature des facteurs utilisée pour le tester qui était trop grossière. L’affirmation a une portée qui dépasse la résolution d’une anomalie statistique. Elle établit que la dotation la plus déterminante d’une économie avancée n’est pas son stock de machines mais son stock de compétences et de connaissances. Elle déplace par conséquent le centre de gravité de l’analyse du commerce vers l’éducation, la formation et la recherche, c’est-à-dire vers des grandeurs que les politiques publiques façonnent directement.",
  'mecanisme': "Trois maillons. Un : la mesure des facteurs incorporés dans les flux commerciaux est reprise, mais en distinguant plusieurs catégories de travail selon le niveau de qualification et en intégrant une mesure du contenu en savoir technologique. Deux : avec cette nomenclature élargie, les exportations américaines apparaissent intensives dans les catégories les plus qualifiées et dans les activités les plus intensives en recherche. Trois : la prédiction du théorème H-O est alors confirmée, puisque les États-Unis sont relativement abondants dans ces facteurs-là. Le modèle est sauvé par l’enrichissement de sa liste de facteurs, ce qui est exactement le programme que suivront les approches néo-factorielles.",
  'exemple': "Le cours relève que Baldwin reprend une méthodologie proche de celle de Leontief et met en évidence le contenu en savoir technologique des exportations américaines.",
  'portee': "Dans le chapitre, Baldwin referme le dossier du paradoxe de Leontief et sert de transition vers les approches néo-factorielles de Keesing et vers la notion de capital humain. Il fournit en outre un argument empirique à la thèse des avantages construits : si l’avantage repose sur la qualification et la connaissance, alors il résulte d’une accumulation délibérée, conforme au mécanisme de Rybczynski.",
  'diss': "À mobiliser pour articuler commerce international et capital humain. Permet de montrer que l’explication du commerce par les dotations n’est pas infirmée mais affinée, et que la politique éducative est une politique commerciale.",
  'copie': "Baldwin montre en 1971 que les exportations américaines sont intensives non en capital physique mais en travail qualifié et en savoir technologique : le paradoxe de Leontief disparaît dès que le travail cesse d’être traité comme homogène.",
  'ouvrage': "Travaux de 1971 sur la structure du commerce extérieur des États-Unis",
  'notions': ['Paradoxe de Leontief', 'Approches néo-factorielles', 'Capital humain'],
  'liens': [('Wassily Leontief', 'prolonge', "Baldwin résout l’anomalie que Leontief avait mise au jour."),
            ('D. Keesing', 'complement', "Keesing systématise la même année l’idée que la qualification est une dotation à part entière."),
            ('T. Rybczynski', 'complement', "Si l’avantage repose sur la qualification, il résulte d’une accumulation délibérée.")],
 }),

 ('D. Keesing', "La qualification du travail devient une dotation factorielle à part entière", {
  'affirme': "Keesing soutient qu’il faut abandonner l’hypothèse d’homogénéité du facteur travail, que le modèle HOS retenait par commodité, et distinguer plusieurs niveaux de qualification. L’affirmation est l’acte fondateur de l’approche néo-factorielle. Elle consiste à conserver intégralement la logique du modèle — l’avantage comparatif naît des différences de dotations relatives — tout en élargissant la liste des facteurs pris en compte. Les pays ne diffèrent plus seulement par le volume de leur main-d’œuvre mais par sa composition : un pays relativement abondant en travail qualifié se spécialisera dans les productions qui en font un usage intensif, un pays abondant en travail peu qualifié dans les autres. Keesing résout ainsi simultanément le paradoxe de Leontief et une faiblesse descriptive du modèle, puisque la structure des qualifications est observable et rend compte de spécialisations que le seul rapport capital sur travail laissait inexpliquées.",
  'mecanisme': "Trois maillons. Un : le travail est décomposé en catégories de qualification, chacune constituant une dotation distincte dont l’abondance relative peut être mesurée. Deux : les productions sont caractérisées par leur intensité en chaque catégorie, de la même manière qu’elles l’étaient en capital et en travail. Trois : le théorème Heckscher-Ohlin s’applique alors inchangé à cette nomenclature élargie, et prédit que chaque pays exporte les biens intensifs dans la catégorie de qualification dont il est relativement le mieux doté. La portée normative suit : la structure des qualifications étant produite par le système éducatif, la spécialisation devient le résultat d’une politique.",
  'exemple': "Le cours souligne que Keesing distingue plusieurs niveaux de qualification et que la notion de capital humain viendra ensuite enrichir encore la liste des dotations.",
  'portee': "Dans le chapitre, Keesing ouvre la partie consacrée aux théories contemporaines et illustre la première des deux stratégies possibles : prolonger les théories traditionnelles plutôt que les remplacer. Il permet aussi d’articuler la théorie du commerce aux analyses de la croissance par le capital humain, et de comprendre pourquoi deux pays de dotations en capital comparables peuvent avoir des spécialisations très différentes.",
  'diss': "À mobiliser pour relier commerce international, qualification et éducation. Argument efficace pour montrer que la spécialisation d’un pays reflète son système de formation autant que son stock de capital.",
  'copie': "Keesing abandonne l’hypothèse d’un travail homogène et fait de la qualification une dotation factorielle à part entière : les pays diffèrent par la composition de leur main-d’œuvre, ce qui conserve le théorème H-O tout en élargissant sa nomenclature de facteurs.",
  'ouvrage': "« Labor Skills and Comparative Advantage », American Economic Review, 1966",
  'notions': ['Approches néo-factorielles', 'Capital humain', 'Dotation factorielle'],
  'liens': [('Robert Baldwin', 'complement', "Les deux travaux convergent pour faire de la qualification la dotation décisive des économies avancées."),
            ('Bertil Ohlin', 'prolonge', "Keesing conserve le théorème H-O en enrichissant sa liste de facteurs."),
            ('M. Posner', 'complement', "L’approche néo-technologique attaque la même insuffisance par un autre côté, celui de l’origine des écarts de productivité.")],
 }),

 ('M. Posner', "L’écart technologique : un avantage comparatif temporaire, érodé par l’imitation", {
  'affirme': "Posner soutient que l’avantage comparatif d’un pays provient de son avance technologique, et que cette avance est par nature provisoire. L’affirmation répond directement à une question que Ricardo laissait ouverte : d’où viennent les écarts de productivité ? Ricardo les constatait et en déduisait la spécialisation sans en expliquer l’origine. Posner répond que ces écarts résultent de l’innovation : le pays qui met au point un procédé ou un produit nouveau produit à un coût que ses concurrents ne peuvent égaler, et exporte donc. Mais cette situation ne dure pas, car les concurrents observent, apprennent et imitent. L’avantage s’érode à mesure que l’écart technologique se comble. Il s’ensuit une conclusion décisive : la position commerciale d’un pays ne dépend pas d’un stock de technologie acquis mais d’un flux continu d’innovations, et un pays qui cesse d’innover perd mécaniquement ses avantages, même sans rien perdre de ses capacités existantes.",
  'mecanisme': "Trois maillons. Un : l’innovation crée un écart de coût ou de qualité en faveur du pays innovateur, qui obtient un avantage comparatif sur le produit concerné. Deux : cet avantage se traduit en exportations tant que les concurrents n’ont pas accès au procédé. Trois : le délai d’imitation — temps nécessaire aux concurrents pour reproduire la technologie — détermine la durée de l’avantage ; passé ce délai, l’écart se réduit puis disparaît. La compétitivité d’une économie se mesure donc à sa capacité à renouveler continuellement ces écarts, c’est-à-dire au rythme de son effort de recherche rapporté à la vitesse d’imitation de ses concurrents.",
  'exemple': "Le cours insiste sur le caractère temporaire de l’avantage : l’imitation réduit progressivement l’écart technologique, ce qui rend la spécialisation instable par construction.",
  'portee': "Dans le chapitre, Posner inaugure les approches néo-technologiques et fournit la clé de la dynamique que Vernon systématisera en cycle de vie du produit. Il permet aussi de relier commerce international et économie de l’innovation : l’effort de recherche cesse d’être une politique sectorielle pour devenir la condition du maintien de la spécialisation.",
  'diss': "À mobiliser dans les sujets sur l’innovation, la compétitivité ou la spécialisation. Permet d’expliquer pourquoi une avance technologique ne protège durablement que si elle est renouvelée, ce que la simple notion d’avantage comparatif ne laisse pas voir.",
  'copie': "Posner explique les écarts de productivité que Ricardo constatait sans les expliquer : l’innovation crée un avantage comparatif que l’imitation érode, de sorte que la spécialisation dépend d’un flux continu d’innovations et non d’un stock acquis.",
  'ouvrage': "« International Trade and Technical Change », Oxford Economic Papers, 1961",
  'notions': ['Écart technologique', 'Approches néo-technologiques', 'Avantage comparatif'],
  'liens': [('Raymond Vernon', 'prolonge', "Le cycle de vie du produit inscrit l’écart technologique dans une séquence complète, de l’innovation à la délocalisation."),
            ('David Ricardo', 'prolonge', "Posner fournit l’explication des écarts de productivité que le modèle ricardien se bornait à constater."),
            ('Paul Krugman', 'complement', "Les rendements croissants offrent une seconde explication des avantages acquis, par le volume plutôt que par la technologie.")],
 }),

 ('Raymond Vernon', "Le cycle de vie international du produit : la production suit la banalisation du procédé", {
  'affirme': "Vernon soutient que la localisation d’une production se déplace au cours de la vie du produit, selon une séquence régulière qui dépend du degré de maturité technique et non des dotations des pays. L’affirmation intègre l’apport de Posner dans un schéma complet et dynamique. Un produit nouveau naît dans un pays à revenu élevé, où une demande solvable et exigeante existe et où la technologie encore incertaine impose la proximité entre conception et fabrication. Il s’exporte ensuite, lorsque la demande étrangère apparaît et que le procédé se stabilise. À maturité, la technologie est standardisée et largement diffusée : le coût devient le critère déterminant, et la production se déplace vers des pays à coûts plus faibles. Le pays innovateur finit alors par importer le produit qu’il avait créé. La conclusion importante est que ce n’est pas le pays qui perd un avantage, c’est le produit qui change de nature.",
  'mecanisme': "Quatre phases que le cours détaille. Un : la naissance, où la production reste concentrée dans le pays innovateur, la technologie étant instable et la demande encore limitée aux consommateurs les plus aisés. Deux : la croissance, où la demande étrangère se développe et où le pays innovateur exporte, tout en conservant la maîtrise du procédé. Trois : la maturité, où le procédé est standardisé, les économies d’échelle réalisées et la concurrence par les prix dominante : la production se délocalise vers les économies à bas coûts. Quatre : le retournement des flux, le pays innovateur devenant importateur net. Chaque phase se déduit de l’état de la technologie et de la structure de la demande.",
  'exemple': "Le cours suit le cycle international des téléviseurs à écran plat, de l’innovation japonaise à la production coréenne puis chinoise et vietnamienne, qui illustre chacune des quatre phases.",
  'portee': "Dans le chapitre, Vernon fournit l’explication la plus complète du déplacement des productions et permet de comprendre la désindustrialisation autrement que comme le résultat d’une concurrence déloyale : elle est la contrepartie normale de la banalisation technique. Il éclaire aussi, en articulation avec le chapitre sur les firmes multinationales, la logique des investissements directs verticaux.",
  'diss': "Référence centrale dans les sujets sur la désindustrialisation, l’innovation et la division internationale du travail. Permet de distinguer une perte d’avantage et un changement de nature du produit, distinction que les copies confondent souvent.",
  'copie': "Vernon décrit quatre phases — naissance dans le pays innovateur, exportation, maturité et délocalisation, importation finale — et montre ainsi que le déplacement de la production suit la banalisation du procédé : ce n’est pas le pays qui perd son avantage, c’est le produit qui change de nature.",
  'ouvrage': "« International Investment and International Trade in the Product Cycle », Quarterly Journal of Economics, 1966",
  'notions': ['Cycle de vie international du produit', 'Écart technologique', 'Approches néo-technologiques'],
  'liens': [('M. Posner', 'prolonge', "Vernon inscrit l’écart technologique temporaire de Posner dans une séquence complète."),
            ('Staffan Burenstam Linder', 'complement', "Les deux analyses font de la demande intérieure la condition d’apparition d’un avantage."),
            ('Dani Rodrik', 'complement', "Le cycle explique le déplacement des productions, Rodrik ce qui arrive aux pays qui en sortent trop tôt.")],
 }),

 ('Edward Chamberlin', "La concurrence monopolistique : la structure de marché qui rend le commerce croisé intelligible", {
  'affirme': "Chamberlin soutient que la plupart des marchés réels ne relèvent ni de la concurrence parfaite ni du monopole, mais d’une configuration intermédiaire qu’il nomme concurrence monopolistique : de nombreux producteurs y offrent des produits différenciés, l’entrée reste libre, et chacun détient un petit pouvoir de marché sur sa propre variété sans échapper pour autant à la pression concurrentielle. L’apport est décisif pour la théorie du commerce international, bien que Chamberlin ne l’ait pas formulé dans cette perspective. En abandonnant l’hypothèse d’homogénéité des produits, que Ricardo posait explicitement parmi ses quatre hypothèses, il rend intelligible un fait que les théories traditionnelles ne pouvaient expliquer : l’échange simultané, dans les deux sens, de produits appartenant à la même branche. Deux automobiles cessent d’être le même bien, et leur échange croisé cesse d’être contradictoire.",
  'mecanisme': "Trois maillons. Un : la différenciation peut être horizontale, lorsque les produits se distinguent par leurs caractéristiques à qualité comparable — style, options, image — et que le choix du consommateur relève de la préférence ; ou verticale, lorsqu’elle hiérarchise les gammes et se traduit par des écarts de prix. Deux : chaque producteur détient un pouvoir de marché limité sur sa variété, ce qui lui permet de fixer un prix supérieur au coût marginal tout en restant exposé à l’entrée de concurrents. Trois : les consommateurs, ayant des préférences diverses, demandent plusieurs variétés : la demande se fragmente, et il devient avantageux pour un pays d’importer des variétés qu’il ne produit pas tout en exportant les siennes.",
  'exemple': "Le cours relève que Lassudrie-Duchêne reprend explicitement l’analyse de la concurrence monopolistique développée par Chamberlin pour construire la notion de demande de différence.",
  'portee': "Dans le chapitre, Chamberlin fournit le cadre de marché sans lequel les analyses de la demande et celles de Krugman seraient impossibles : la différenciation est la condition logique du commerce intra-branche. Son apport marque aussi le point où les théories contemporaines cessent de prolonger les traditionnelles pour en abandonner une hypothèse constitutive.",
  'diss': "À mobiliser dès qu’un sujet porte sur le commerce entre pays semblables, sur la différenciation ou sur le réalisme de la concurrence parfaite. La distinction horizontale/verticale est particulièrement utile pour traiter l’échange entre pays de niveaux de développement différents.",
  'copie': "Chamberlin décrit en 1933 une concurrence monopolistique — produits différenciés, pouvoir de marché limité, libre entrée — qui, en abandonnant l’hypothèse d’homogénéité des produits, rend intelligible l’échange croisé de biens appartenant à la même branche.",
  'ouvrage': "The Theory of Monopolistic Competition, 1933",
  'notions': ['Concurrence monopolistique', 'Différenciation horizontale', 'Différenciation verticale', 'Commerce intra-branche'],
  'liens': [('Bernard Lassudrie-Duchêne', 'prolonge', "La demande de différence s’appuie directement sur la concurrence monopolistique de Chamberlin."),
            ('Paul Krugman', 'prolonge', "Krugman associe concurrence monopolistique et rendements croissants pour fonder la nouvelle théorie du commerce."),
            ('David Ricardo', 'opposition', "L’homogénéité des produits, posée en hypothèse par Ricardo, est précisément ce que Chamberlin abandonne.")],
 }),

 ('Bernard Lassudrie-Duchêne', "La demande de différence : les consommateurs veulent ce que leur industrie ne produit pas", {
  'affirme': "Lassudrie-Duchêne soutient que l’explication du commerce entre pays semblables doit être cherchée du côté de la demande et non de l’offre. Le renversement est important : toutes les théories traditionnelles, de Ricardo au modèle HOS, expliquent l’échange par des caractéristiques de l’offre — productivités, dotations, technologies. Lassudrie-Duchêne observe qu’à l’intérieur d’une même branche les consommateurs d’un pays recherchent précisément des produits qui diffèrent de ceux que leur industrie nationale propose, qu’il s’agisse d’un style, d’une réputation, d’une gamme ou d’une origine. Cette demande de différence suffit à engendrer un commerce croisé entre pays dont les structures productives sont pourtant comparables. La notion explique ainsi le fait le plus massif du commerce contemporain, l’échange intra-branche entre économies avancées, sans recourir à aucune asymétrie de dotations ou de productivités.",
  'mecanisme': "Trois maillons. Un : la concurrence monopolistique de Chamberlin fournit le cadre, en admettant que les produits d’une même branche ne soient pas substituables parfaits. Deux : les préférences des consommateurs étant hétérogènes à l’intérieur de chaque pays, une partie de la demande nationale s’adresse à des variétés que l’industrie locale ne propose pas, ou propose moins bien. Trois : chaque pays importe donc ces variétés tout en exportant les siennes vers ses partenaires, où la même logique opère. Le commerce résulte de la diversité des goûts et de la différenciation de l’offre, non de différences entre pays : il croît avec la similitude des niveaux de vie, qui élargit le champ des variétés accessibles.",
  'exemple': "Le cours cite les automobiles et les vins, échangés simultanément dans les deux sens entre pays producteurs comparables.",
  'portee': "Dans le chapitre, cette notion fournit la première explication complète du commerce intra-branche, c’est-à-dire de la limite décisive opposée aux théories traditionnelles. Elle ouvre la partie consacrée au rôle de la demande, que Linder prolongera, et prépare l’analyse de Krugman en montrant que la variété est en soi un objet d’échange.",
  'diss': "À mobiliser impérativement dans tout sujet portant sur le commerce entre pays semblables. Argument fort pour montrer que la théorie du commerce a changé d’objet : elle explique désormais des flux que les différences entre pays ne peuvent produire.",
  'copie': "Lassudrie-Duchêne déplace l’explication du commerce de l’offre vers la demande : les consommateurs recherchent, dans une même branche, des produits différents de l’offre nationale, et cette demande de différence suffit à engendrer un échange croisé entre pays comparables.",
  'ouvrage': "Travaux sur la demande de différence et l’échange intra-branche",
  'notions': ['Demande de différence', 'Commerce intra-branche', 'Concurrence monopolistique'],
  'liens': [('Edward Chamberlin', 'prolonge', "La demande de différence s’appuie sur la concurrence monopolistique comme cadre de marché."),
            ('Staffan Burenstam Linder', 'complement', "Linder relie la structure de la demande intérieure à la géographie observée des échanges."),
            ('Bertil Ohlin', 'opposition', "Le commerce intra-branche entre pays comparables est inexplicable par les seules différences de dotations.")],
 }),

 ('Staffan Burenstam Linder', "La demande représentative : on exporte ce que son marché intérieur a appris à produire", {
  'affirme': "Linder soutient qu’un avantage comparatif ne précède pas la demande mais en résulte. Une industrie ne devient capable d’exporter qu’après avoir servi un marché intérieur suffisamment important : c’est en répondant à une demande domestique forte et exigeante qu’elle acquiert l’échelle, l’expérience, les circuits de distribution et la maîtrise technique nécessaires à la conquête de marchés étrangers. Linder en déduit une prédiction qui contredit frontalement celle du modèle HOS : les pays échangent d’autant plus qu’ils se ressemblent. Si l’avantage naît de la demande intérieure, alors les débouchés extérieurs les plus accessibles se trouvent dans les pays dont les consommateurs demandent des produits comparables, c’est-à-dire dont le niveau de vie et la structure de consommation sont semblables. Le modèle HOS prédisait au contraire un commerce d’autant plus intense que les dotations diffèrent.",
  'mecanisme': "Trois maillons. Un : une demande intérieure forte sur un produit permet à l’industrie nationale d’atteindre une taille de production qui abaisse ses coûts unitaires et affine son savoir-faire. Deux : l’industrie acquiert ainsi, sur ce produit, une compétitivité qu’elle n’aurait pu obtenir en visant d’emblée l’exportation, car la demande étrangère est plus coûteuse à prospecter et moins bien connue. Trois : les débouchés extérieurs les plus naturels sont ceux dont la demande ressemble à celle du marché d’origine, ce qui concentre les échanges entre pays de niveau de vie comparable. La structure de la consommation devient ainsi un déterminant du commerce au même titre que les dotations.",
  'exemple': "Le cours relève que les pays échangent davantage avec les économies dont les consommateurs leur ressemblent, ce qui correspond à la concentration observée des flux entre pays développés.",
  'portee': "Dans le chapitre, Linder complète l’explication du commerce intra-branche par la demande et apporte un élément que Lassudrie-Duchêne ne contenait pas : la géographie des échanges. Il fournit aussi un argument aux analyses de la politique industrielle, puisque la taille et l’exigence du marché intérieur deviennent des conditions de la compétitivité extérieure — argument que l’on retrouve dans la première des trois conditions du protectionnisme éducateur.",
  'diss': "À mobiliser pour expliquer la géographie du commerce mondial, concentrée entre pays riches, et pour relier marché intérieur et compétitivité extérieure. Très utile en contrepoint du modèle HOS, dont il inverse la prédiction.",
  'copie': "Linder soutient qu’une forte demande intérieure précède l’avantage comparatif : l’industrie acquiert d’abord sur son marché national l’échelle et l’expérience nécessaires, puis exporte vers les pays dont les consommateurs lui ressemblent — prédiction inverse de celle du modèle HOS.",
  'ouvrage': "Travaux sur la demande représentative et la similitude des structures de consommation",
  'notions': ['Demande représentative', 'Commerce intra-branche', 'Demande de différence'],
  'liens': [('Bernard Lassudrie-Duchêne', 'complement', "Les deux analyses expliquent le commerce par la demande, l’une par sa diversité, l’autre par son niveau."),
            ('Bertil Ohlin', 'opposition', "Linder prédit un commerce d’autant plus intense que les pays se ressemblent, HOS l’inverse."),
            ('Friedrich List', 'complement', "La condition d’un marché intérieur suffisant est commune à Linder et au protectionnisme éducateur.")],
 }),

 ('Paul Krugman', "Rendements croissants : trois gains à l’ouverture, même entre pays identiques", {
  'affirme': "Krugman soutient que l’ouverture commerciale est avantageuse même entre deux pays strictement identiques, ce qui constitue une rupture avec l’ensemble de la tradition antérieure. Toutes les théories précédentes faisaient naître l’échange d’une différence : de productivité chez Ricardo, de dotations dans le modèle HOS, de technologie chez Posner. Krugman montre qu’en présence de rendements d’échelle croissants et de produits différenciés, la seule taille du marché suffit à engendrer un gain. Trois gains distincts en résultent. Le premier est un gain de concurrence et de sélection : l’ouverture expose les producteurs nationaux à des concurrents supplémentaires, et les moins efficaces disparaissent. Le second est un gain de variété : les consommateurs accèdent à un ensemble de produits plus large que celui que leur industrie nationale pouvait offrir. Le troisième est un effet de dimension : le marché élargi permet d’exploiter les économies d’échelle et d’abaisser les coûts unitaires.",
  'mecanisme': "Les trois gains procèdent du même point de départ. Un : l’existence de rendements croissants signifie que le coût unitaire décroît avec la quantité produite, de sorte qu’aucune firme ne peut servir qu’un marché étroit à faible coût. Deux : l’ouverture additionne les marchés nationaux, ce qui permet à chaque firme de produire en plus grande quantité et donc à moindre coût unitaire — c’est l’effet de dimension. Trois : comme le nombre de concurrents augmente simultanément, les moins efficaces sont évincés et la production se concentre sur les plus performants — c’est l’effet de sélection. Quatre : les variétés survivantes provenant de plusieurs pays, l’éventail disponible pour le consommateur s’élargit — c’est l’effet de variété. Aucun de ces trois mécanismes ne requiert de différence entre les pays.",
  'exemple': "Le cours illustre le mécanisme par l’exemple de la production de boutons entre la Chine et l’Europe, où l’ouverture renforce la spécialisation par les économies d’échelle et fait davantage baisser les prix du côté où la demande initiale était la plus forte.",
  'portee': "Dans le chapitre, Krugman fonde les théories contemporaines au sens strict, celles qui ne prolongent pas le cadre traditionnel mais le remplacent. Son résultat explique le commerce intra-branche du côté de l’offre, là où Lassudrie-Duchêne et Linder l’expliquaient par la demande, et il ouvre la voie à l’analyse de l’agglomération puis à la réhabilitation partielle du protectionnisme éducateur.",
  'diss': "Référence indispensable dès qu’un sujet porte sur les gains de l’ouverture ou sur le commerce entre pays semblables. Les trois gains fournissent un plan de sous-partie immédiatement utilisable et évitent de réduire le gain à l’échange à l’argument allocatif.",
  'copie': "Krugman établit que l’ouverture procure trois gains — sélection des producteurs les plus efficaces, variété accrue, effet de dimension — même entre pays strictement identiques : avec des rendements croissants, c’est la taille du marché et non la différence entre pays qui crée le gain.",
  'ouvrage': "« Increasing Returns, Monopolistic Competition, and International Trade », 1979",
  'notions': ['Rendements d’échelle croissants', 'Gains de l’ouverture selon Krugman', 'Économies d’échelle internes', 'Concurrence monopolistique'],
  'liens': [('Edward Chamberlin', 'prolonge', "Krugman associe la concurrence monopolistique de Chamberlin aux rendements croissants."),
            ('David Ricardo', 'opposition', "Le gain à l’échange cesse de dépendre d’une différence entre pays."),
            ('Alfred Marshall', 'complement', "Les économies d’échelle externes de Marshall complètent les économies internes mobilisées ici.")],
 }),

 ('Paul Krugman', "La nouvelle géographie économique : la localisation initiale engendre l’avantage", {
  'affirme': "Krugman soutient que la causalité admise par les théories traditionnelles doit être inversée. Dans ces théories, la dotation d’un territoire détermine ce qui s’y produit : on fabrique du vin là où le climat le permet, des biens intensifs en capital là où le capital est abondant. Krugman montre qu’en présence de rendements croissants et d’externalités de localisation, c’est l’implantation initiale d’une activité qui engendre l’avantage du territoire, et non l’inverse. Une première installation, parfois accidentelle, parfois suscitée par une décision publique, permet d’atteindre un volume de production qui abaisse les coûts ; elle attire alors fournisseurs, main-d’œuvre qualifiée et concurrents, dont la présence renforce à son tour l’attractivité du lieu. Le processus est cumulatif et largement irréversible : l’avantage comparatif devient acquis, et son origine cesse d’être explicable par les caractéristiques initiales du territoire.",
  'mecanisme': "Quatre maillons. Un : une activité s’installe en un lieu donné, pour une raison qui peut être contingente. Deux : les rendements croissants font baisser son coût unitaire à mesure que la production augmente, ce qui renforce sa position. Trois : les trois externalités identifiées par Marshall opèrent alors — des fournisseurs spécialisés s’implantent à proximité, un bassin de main-d’œuvre qualifiée se constitue, les connaissances circulent informellement — et élèvent la productivité de toutes les firmes présentes. Quatre : cette productivité supérieure attire de nouvelles entreprises, ce qui renforce encore les externalités. La boucle se referme : l’agglomération se nourrit d’elle-même et devient très difficile à concurrencer depuis un autre territoire.",
  'exemple': "Le cours détaille trois cas : Bangalore, où une implantation initiale déclenche une agglomération ; Toulouse, où l’État amorce le processus ; la Silicon Valley, où une innovation initiale, adossée à Stanford et aux travaux de Hewlett et Packard, enclenche des effets cumulatifs.",
  'portee': "Dans le chapitre, cette idée donne son contenu à la thèse des avantages acquis et constitue le fondement théorique de la politique industrielle territoriale. Elle explique la persistance des spécialisations régionales que ni les dotations ni les coûts n’expliquent, et elle prépare l’argument du seuil critique, puisqu’un territoire non encore agglomeré peut rester durablement exclu.",
  'diss': "À mobiliser dans les sujets sur la localisation des activités, les politiques d’attractivité et la spécialisation. Permet de montrer qu’une politique publique peut créer un avantage comparatif sans contredire la logique économique, puisqu’elle agit sur un mécanisme cumulatif.",
  'copie': "Krugman inverse la causalité traditionnelle : avec des rendements croissants et les externalités marshalliennes, c’est l’implantation initiale — parfois accidentelle, parfois publique — qui engendre l’avantage du territoire, et l’agglomération qui en résulte le rend durable.",
  'ouvrage': "Geography and Trade, 1991",
  'notions': ['Nouvelle géographie économique', 'Effet d’agglomération', 'Économies d’échelle externes', 'Avantage comparatif construit'],
  'liens': [('Alfred Marshall', 'prolonge', "Krugman mobilise les trois externalités du district industriel pour expliquer le caractère cumulatif de l’agglomération."),
            ('T. Rybczynski', 'complement', "Deux voies de construction de l’avantage : l’accumulation de facteurs et l’agglomération."),
            ('Bertil Ohlin', 'opposition', "La dotation n’explique plus la localisation : c’est la localisation qui produit l’avantage.")],
 }),

 ('Paul Krugman', "Le seuil critique : l’ouverture immédiate peut empêcher l’émergence d’une industrie viable", {
  'affirme': "Krugman soutient que, en présence de rendements croissants, un producteur potentiellement plus efficace qu’un concurrent installé peut rester durablement exclu du marché. L’affirmation est la conséquence logique des deux précédentes, mais elle a une portée normative considérable car elle fournit une justification théorique au protectionnisme éducateur que la théorie standard traitait comme une curiosité historique. Le raisonnement est le suivant : si le coût unitaire décroît avec le volume, il existe une quantité seuil au-delà de laquelle une production devient compétitive. Un entrant doit donc, pour être viable, atteindre d’emblée ce seuil ; or il ne peut vendre tant qu’il n’est pas compétitif, et il ne peut être compétitif tant qu’il ne vend pas. Le concurrent déjà installé, qui a franchi le seuil, conserve le marché quelle que soit son efficacité potentielle relative. L’antériorité, et non l’efficacité, décide de la spécialisation.",
  'mecanisme': "Quatre maillons. Un : la fonction de coût unitaire est décroissante, de sorte qu’il existe un volume Q0 au-delà duquel le producteur devient compétitif. Deux : l’entrant, partant d’une production nulle, affiche un coût unitaire supérieur à celui du concurrent installé et ne peut donc vendre au prix du marché. Trois : il ne peut par conséquent atteindre Q0, et le seuil fonctionne comme une barrière à l’entrée qu’aucune efficacité potentielle ne permet de franchir. Quatre : une protection temporaire, en réservant le marché domestique à l’entrant, lui permet d’atteindre Q0, après quoi l’ouverture peut être rétablie. Trois conditions sont alors indispensables : un marché intérieur assez vaste pour contenir Q0, le maintien d’une concurrence interne pour préserver l’incitation à réduire les coûts, et une protection strictement temporaire.",
  'exemple': "Le cours construit l’exemple de la Chine et du Vietnam : le Vietnam, potentiellement plus efficace, reste hors du marché faute de pouvoir atteindre le seuil Q0 face à une industrie chinoise déjà installée.",
  'portee': "Dans le chapitre, cette idée assure la jonction entre les théories contemporaines et la quatrième partie consacrée au débat libre-échange / protectionnisme : elle transforme un argument historique, celui de List, en résultat théorique. Elle fixe aussi les conditions précises auxquelles la protection peut être utile, ce qui fournit la grille d’évaluation reprise ensuite pour les politiques contemporaines de semi-conducteurs et de technologies vertes.",
  'diss': "Argument décisif dans tout sujet sur le protectionnisme ou la politique industrielle. Toujours l’énoncer avec les trois conditions : sans elles, l’argument du seuil critique devient un plaidoyer pour la protection permanente.",
  'copie': "Krugman montre qu’avec des rendements croissants un producteur plus efficace peut rester sous le seuil Q0 face à un concurrent installé : l’ouverture immédiate empêche alors l’émergence d’une industrie viable, ce qui réhabilite le protectionnisme éducateur sous trois conditions strictes.",
  'ouvrage': "« Increasing Returns, Monopolistic Competition, and International Trade », 1979 ; Geography and Trade, 1991",
  'notions': ['Seuil critique de production', 'Protectionnisme éducateur', 'Industrie naissante', 'Trois conditions du protectionnisme éducateur'],
  'liens': [('Friedrich List', 'prolonge', "Krugman fournit la formalisation de l’argument des industries naissantes que List avait énoncé en 1841."),
            ('James Brander', 'complement', "La politique commerciale stratégique prolonge l’argument en situation d’oligopole international."),
            ('Nicholas Kaldor', 'complement', "Kaldor transpose la protection temporaire aux industries en déclin.")],
 }),

 ('Alfred Marshall', "Les districts industriels : trois externalités rendent la localisation productive", {
  'affirme': "Marshall soutient que la productivité d’une entreprise ne dépend pas seulement de ses propres caractéristiques mais aussi de son environnement immédiat, et qu’il existe par conséquent des économies d’échelle externes, liées à la taille du secteur ou du territoire et non à celle de la firme. L’observation de la concentration géographique d’entreprises d’une même branche — ce qu’il nomme district industriel — le conduit à identifier trois avantages précis que procure la proximité. La portée de cette thèse est considérable : elle introduit dans l’analyse économique l’idée qu’un lieu peut être en lui-même un facteur de production, et que la performance d’une firme s’explique en partie par des éléments qu’elle ne contrôle pas et qu’elle ne paie pas. Elle fournit ainsi le fondement micro-économique des analyses contemporaines de l’agglomération et de la localisation internationale des activités.",
  'mecanisme': "Les trois externalités que le cours détaille. Un : la proximité de fournisseurs spécialisés réduit les coûts d’approvisionnement, raccourcit les délais et permet une adaptation fine des intrants aux besoins, ce qui serait impossible à distance. Deux : la constitution d’un vaste bassin de main-d’œuvre spécialisée réduit le coût et le risque du recrutement pour les entreprises et le risque de chômage pour les salariés, ce qui attire les unes et les autres. Trois : les externalités de connaissance font circuler informellement les savoir-faire, par la mobilité des salariés, les relations personnelles et l’observation mutuelle, de sorte que chaque innovation profite partiellement à tous. Ces trois effets croissent avec la densité du district et se renforcent mutuellement.",
  'exemple': "Le cours mobilise ces trois externalités pour expliquer les cas contemporains d’agglomération que Krugman analyse, de Bangalore à la Silicon Valley.",
  'portee': "Dans le chapitre, Marshall fournit le mécanisme sans lequel la nouvelle géographie économique resterait une description : c’est parce que les externalités de proximité existent que l’implantation initiale produit un avantage cumulatif. Il permet aussi de distinguer rigoureusement économies d’échelle internes et externes, distinction indispensable pour comprendre que la spécialisation d’un territoire ne se ramène pas à la taille de ses entreprises.",
  'diss': "À mobiliser dans les sujets sur la localisation, les politiques territoriales et la compétitivité. La distinction interne/externe est un réflexe attendu dès que l’on parle d’économies d’échelle.",
  'copie': "Marshall identifie dès 1890 trois externalités du district industriel — fournisseurs spécialisés, bassin de main-d’œuvre qualifiée, circulation informelle des connaissances — qui rendent une firme plus productive parce que d’autres firmes sont présentes : la localisation devient un facteur de production.",
  'ouvrage': "Principes d’économie politique, 1890",
  'notions': ['District industriel', 'Externalités marshalliennes', 'Économies d’échelle externes', 'Effet d’agglomération'],
  'liens': [('Paul Krugman', 'complement', "La nouvelle géographie économique transforme ces externalités en mécanisme cumulatif de localisation."),
            ('T. Rybczynski', 'complement', "Les deux approches font de l’avantage un résultat de l’accumulation plutôt qu’une donnée.")],
 }),

 ('Dani Rodrik', "La désindustrialisation précoce : perdre son industrie avant d’être riche", {
  'affirme': "Rodrik soutient que de nombreux pays en développement voient la part de l’industrie dans l’emploi et la valeur ajoutée décliner à un niveau de revenu par habitant très inférieur à celui auquel les économies aujourd’hui avancées ont connu le même retournement. Le constat est d’une portée considérable pour l’analyse du commerce international. Historiquement, l’industrialisation a constitué le mécanisme central du rattrapage : elle absorbe une main-d’œuvre peu qualifiée en provenance de l’agriculture, lui procure des gains de productivité rapides et élève les salaires, tout en engendrant des capacités techniques transférables. Un pays qui se désindustrialise avant d’avoir atteint un niveau de revenu élevé se trouve privé de ce moteur sans disposer de l’alternative que les services à forte productivité constituent dans les économies avancées. La spécialisation que le commerce lui assigne peut donc être rationnelle à court terme et bloquante à long terme.",
  'mecanisme': "Trois maillons. Un : l’ouverture expose l’industrie naissante de ces pays à des concurrents déjà installés, qui bénéficient d’économies d’échelle et d’agglomération — c’est exactement la configuration du seuil critique analysée par Krugman. Deux : l’industrie locale se cantonne alors aux segments à faible valeur ajoutée ou disparaît, et la main-d’œuvre se reporte vers des services peu productifs plutôt que vers l’industrie. Trois : les capacités techniques et organisationnelles qui accompagnent l’industrialisation ne se constituent pas, de sorte que la montée en gamme ultérieure devient improbable. L’économie se stabilise à un niveau de revenu intermédiaire, sans mécanisme endogène de rattrapage.",
  'exemple': "Le cours rattache ce diagnostic aux spécialisations primaires et à la reprimarisation, dont le cas brésilien fournit l’illustration : rentable à court terme, pauvre en effets d’entraînement.",
  'portee': "Dans le chapitre, Rodrik renouvelle la critique des spécialisations défavorables en la détachant du cadre néo-marxiste : l’argument ne repose plus sur une domination mais sur un mécanisme d’économie industrielle. Il fournit ainsi l’argument contemporain le plus solide à l’appui de la thèse que toutes les spécialisations ne se valent pas, et justifie l’attention portée au contenu de l’insertion internationale plutôt qu’à son intensité.",
  'diss': "Référence centrale dans les sujets sur le développement, l’industrialisation et la spécialisation. Permet d’actualiser la critique de Prebisch sans se heurter à l’objection du rattrapage des émergents.",
  'copie': "Rodrik établit que de nombreux pays en développement se désindustrialisent à un niveau de revenu très inférieur à celui des pays avancés en leur temps : la désindustrialisation précoce les prive du principal moteur historique de rattrapage sans leur en offrir de substitut.",
  'ouvrage': "Travaux sur la désindustrialisation précoce et les trajectoires de développement",
  'notions': ['Désindustrialisation précoce', 'Reprimarisation', 'Insertion dominée'],
  'liens': [('Raúl Prebisch', 'prolonge', "Rodrik renouvelle la critique des spécialisations défavorables sur un fondement d’économie industrielle."),
            ('Paul Krugman', 'complement', "Le seuil critique explique pourquoi l’industrie naissante de ces pays ne parvient pas à s’établir."),
            ('Friedrich List', 'complement', "Le diagnostic réactive l’argument de la protection temporaire des industries naissantes.")],
 }),

 ('Dani Rodrik', "Le paradigme productiviste : la politique économique change d’objectif", {
  'affirme': "Rodrik soutient qu’un déplacement majeur s’opère dans les objectifs assignés à la politique économique des pays avancés. Pendant plusieurs décennies, l’efficience allocative et la libéralisation des échanges ont constitué le critère dominant : une politique était jugée bonne si elle rapprochait l’économie d’une allocation optimale des ressources. Rodrik observe que ce critère cède la place à un autre, qu’il nomme paradigme productiviste : l’objectif devient la création d’emplois de qualité et la préservation de capacités productives localisées. Le changement ne porte pas d’abord sur les instruments, qui peuvent rester les mêmes, mais sur la hiérarchie des finalités. Il en résulte une réhabilitation de la politique industrielle et une tolérance nouvelle à l’égard de mesures qui, évaluées au seul critère de l’efficience, seraient condamnées. L’analyse permet ainsi de comprendre le retour du protectionnisme autrement que comme une erreur de raisonnement.",
  'mecanisme': "Trois maillons. Un : la non-prise en charge des coûts d’ajustement de l’ouverture a concentré des pertes durables sur des catégories et des territoires identifiables, ce que la courbe de l’éléphant donne à voir. Deux : ce coût politique rend la poursuite de l’efficience allocative pure difficilement soutenable dans une démocratie, puisque les perdants disposent du bulletin de vote. Trois : la politique économique se réoriente alors vers des objectifs directement observables par les électeurs — emplois, usines, filières — ce qui conduit à préférer des instruments de politique industrielle à des gains de surplus diffus. Le protectionnisme contemporain apparaît ainsi comme la conséquence d’une défaillance antérieure de la politique de répartition.",
  'exemple': "Le cours rattache cette analyse aux politiques contemporaines de soutien aux semi-conducteurs et aux technologies vertes, où la localisation de la production devient un objectif explicite.",
  'portee': "Dans le chapitre, cette idée fournit le cadre interprétatif du retour du protectionnisme et du basculement que documentent Emlinger, Guimbard et Lefebvre. Elle permet de distinguer la question analytique — ces politiques sont-elles efficaces ? — de la question politique — pourquoi sont-elles adoptées ? — et d’éviter de réduire le protectionnisme contemporain à une ignorance économique.",
  'diss': "À mobiliser en ouverture ou en troisième partie des sujets sur le retour du protectionnisme et sur la politique industrielle. Argument fort pour montrer que le débat a changé de termes, et non seulement de niveau tarifaire.",
  'copie': "Rodrik décrit en 2022 l’émergence d’un paradigme productiviste : la politique économique se recentre sur la qualité des emplois et les capacités productives localisées plutôt que sur l’efficience allocative, ce qui éclaire le retour du protectionnisme sans le réduire à une erreur d’analyse.",
  'ouvrage': "« L’émergence du paradigme productiviste », 2022",
  'notions': ['Paradigme productiviste', 'Politique industrielle', 'Habits neufs du protectionnisme'],
  'liens': [('Guillaume Vuillemey', 'complement', "Les deux analyses justifient la protection par autre chose que la défense d’intérêts sectoriels."),
            ('C. Emlinger', 'complement', "La nouvelle hiérarchie des objectifs documente empiriquement le déplacement que Rodrik décrit."),
            ('Branko Milanovic', 'prolonge', "Le coût politique mesuré par la courbe de l’éléphant fournit le ressort du basculement.")],
 }),

 ('Branko Milanovic', "La courbe de l’éléphant : le coût politique de la mondialisation a une forme mesurable", {
  'affirme': "Milanović soutient que les effets distributifs de la mondialisation ne se lisent pas à l’échelle des pays mais à celle de la distribution mondiale des revenus, et il en propose une représentation devenue célèbre. En classant la population mondiale par centile de revenu et en mesurant la croissance du revenu réel de chaque centile entre 1988 et 2008, il obtient une courbe dont le profil évoque un éléphant : forte progression pour les centiles intermédiaires, correspondant aux classes moyennes des pays émergents ; progression également forte pour le sommet de la distribution ; en revanche, quasi-stagnation pour les centiles situés juste en dessous, où se trouvent les classes populaires et moyennes des pays avancés. La mondialisation a donc produit des gains considérables, mais ils ont contourné des catégories nombreuses et politiquement décisives dans les démocraties riches.",
  'mecanisme': "Trois maillons. Un : la convergence entre pays, que le théorème d’égalisation du prix des facteurs annonce, élève les revenus des travailleurs des économies émergentes, ce qui explique la bosse centrale. Deux : le théorème Stolper-Samuelson prévoit simultanément le recul de la rémunération réelle du facteur relativement rare dans les pays avancés, c’est-à-dire du travail peu qualifié : c’est le creux. Trois : la concentration des revenus du capital et des très hautes qualifications explique la remontée terminale. La courbe n’est donc pas une anomalie mais la forme empirique de ce que la théorie prévoyait, à ceci près que l’ampleur du creux et sa persistance ont été sous-estimées — ce que Krugman reconnaît en 2019.",
  'exemple': "Le cours rapproche explicitement l’analyse de Milanović de l’idée que les coûts de la mondialisation ne sont pas seulement économiques mais aussi politiques.",
  'portee': "Dans le chapitre, la courbe de l’éléphant fournit la mesure du coût politique de la mondialisation et explique le retour du protectionnisme comme un paradoxe seulement apparent. Elle permet de tenir ensemble deux faits que l’on oppose souvent à tort : la réduction des inégalités entre pays et l’accroissement de certaines inégalités à l’intérieur des pays avancés.",
  'diss': "Référence incontournable dans les sujets sur les inégalités, la mondialisation et le protectionnisme. À mobiliser pour articuler les deux niveaux d’analyse et pour relier un résultat économique à une conséquence politique.",
  'copie': "La courbe de l’éléphant de Milanović montre que la croissance des revenus réels entre 1988 et 2008 a été forte pour les classes moyennes émergentes et pour le sommet de la distribution, mais quasi nulle pour les classes populaires des pays avancés : le coût de la mondialisation est concentré sur des catégories politiquement décisives.",
  'ouvrage': "Travaux sur la répartition mondiale des revenus (courbe de l’éléphant)",
  'notions': ['Courbe de l’éléphant', 'Hypermondialisation', 'Théorème Stolper-Samuelson'],
  'liens': [('Wolfgang Stolper', 'prolonge', "La courbe donne une forme empirique au creux que le théorème prévoit dans les pays avancés."),
            ('Paul Samuelson', 'complement', "La convergence entre pays et la divergence interne sont les deux versants du même mécanisme."),
            ('Dani Rodrik', 'complement', "Le coût politique mesuré ici fournit le ressort du paradigme productiviste.")],
 }),
]
